/usr/bin/bash -lc "perl -MIO::Uncompress::Gunzip -e '
use strict; use warnings;
my ("'$fp,$rp)=@ARGV;
my $f=IO::Uncompress::Gunzip->new($fp) or die "open forward: $IO::Uncompress::Gunzip::GunzipError'"\\n\";
my "'$r=IO::Uncompress::Gunzip->new($rp) or die "open reverse: $IO::Uncompress::Gunzip::GunzipError'"\\n\";
my ("'$pairs,$min_f,$min_r,$max_nf,$max_nr,$max_lqf,$max_lqr)=(0,10**9,10**9,0,0,0,0);
while (1) {
  my @a=map { scalar <$f> } 1..4;
  my @b=map { scalar <$r> } 1..4;
  last if !defined($a[0]) && !defined($b[0]);
  die "mate EOF mismatch'"\\n\" if "'!defined($a[0]) || !defined($b[0]);
  die "truncated FASTQ'"\\n\" if grep { "'!defined } (@a,@b);
  chomp(@a,@b);
  die "invalid FASTQ marker'"\\n\" unless "'$a[0]=~/''^'"\\@/ && "'$b[0]=~/''^'"\\@/ && "'$a[2]=~/''^'"\\+/ && "'$b[2]=~/''^'"\\+/;
  die \"sequence-quality length mismatch\\n\" unless length("'$a[1])==length($a[3]) && length($b[1])==length($b[3]);
  my ($id1,$id2)=map { my $x=$_; $x=~s/''^'"\\@//; "'$x=(split /'"\\s+/, "'$x)[0]; $x=~s{/[12]$}{}; $x } ($a[0],$b[0]);
  die "read ID mismatch at pair ".($pairs+1)."'"\\n\" unless "'$id1 eq $id2;
  my ($lf,$lr)=(length($a[1]),length($b[1]));
  die "read shorter than 15'"\\n\" if "'$lf<15 || $lr<15;
  my $nf=($a[1]=~tr/Nn//); my $nr=($b[1]=~tr/Nn//);
  die "more than 5 Ns'"\\n\" if "'$nf>5 || $nr>5;
  my $lqf=grep { ord($_)-33<20 } split //,$a[3];
  my $lqr=grep { ord($_)-33<20 } split //,$b[3];
  die "more than 40 percent low-quality bases'"\\n\" if "'$lqf/$lf>0.4 || $lqr/$lr>0.4;
  $min_f=$lf if $lf<$min_f; $min_r=$lr if $lr<$min_r;
  $max_nf=$nf if $nf>$max_nf; $max_nr=$nr if $nr>$max_nr;
  $max_lqf=$lqf/$lf if $lqf/$lf>$max_lqf; $max_lqr=$lqr/$lr if $lqr/$lr>$max_lqr;
  $pairs++;
}
printf "pairs=%d min_lengths=%d,%d max_N=%d,%d max_low_quality_fraction=%.6f,%.6f'"\\n\","'$pairs,$min_f,$min_r,$max_nf,$max_nr,$max_lqf,$max_lqr;
'"' final_answer/trimmed_forward.fastqsanger.gz final_answer/trimmed_reverse.fastqsanger.gz
